def json_pointer(doc, pointer: str):
    """Resolve an RFC 6901 JSON Pointer against nested dicts/lists."""
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("pointer must be empty or start with '/'")

    current = doc
    for raw in pointer.split("/")[1:]:
        # '~1' must be decoded before '~0'
        token = raw.replace("~1", "/").replace("~0", "~")

        if isinstance(current, dict):
            if token not in current:
                raise ValueError("missing key: %r" % (token,))
            current = current[token]
        elif isinstance(current, list):
            if token == "" or not all("0" <= c <= "9" for c in token):
                raise ValueError("invalid array index: %r" % (token,))
            idx = int(token)
            if idx >= len(current):
                raise ValueError("array index out of range: %r" % (token,))
            current = current[idx]
        else:
            raise ValueError(
                "cannot index into value of type %s" % type(current).__name__
            )
    return current
```

Notes: the empty pointer returns the document unchanged; each segment is unescaped (`~1` → `/` first, then `~0` → `~`); dict lookups use the decoded segment as a key, list lookups require ASCII decimal digits only (so `+1`, `-1`, ` 1`, `1.0`, and `-` all raise `ValueError`), and any other container type raises `ValueError`.
